async function saveShort158(){if(!shortAsset158||!shortData158)return;syncShortMain158();const b=$('#shortSave158'),old=b.textContent;b.disabled=true;b.textContent='Speichere …';try{const x=await vault158('/knowledge/youtube-short/import','POST',{assetId:shortAsset158.id,content:JSON.stringify(shortData158),provider:'manual',model:'BD Short Studio v3',promptVersionId:shortPrompt158?.id||''});shortAsset158=x.asset;shortData158=x.short;renderShortEditor158();notice158(`Short als Draft V${x.asset?.drafts?.[0]?.version||''} gespeichert.`);await loadCreator158(true)}catch(e){notice158(e.message,'warn')}finally{b.disabled=false;b.textContent=old}}

function patchArtifactButtons158(){document.addEventListener('click',e=>{const b=e.target.closest('[data-existing-artifact157],[data-artifact-id157]');if(!b||b.dataset.type!=='video_script')return;const id=b.dataset.existingArtifact157||b.dataset.artifactId157;if(!id)return;e.preventDefault();e.stopImmediatePropagation();const src=window.BDHub148?.currentSource?.();const sourceId=src?.id||window.BDHub148?.artifactSource?.()||'';const projectId=window.BDHub148?.currentProject?.()||window.BDHub148?.artifactProject?.()||'';if(sourceId){$('#repurposeDialog148')?.close?.();$('#articleArtifacts157')?.close?.();openShortFromArtifact158(sourceId,id,projectId)}} ,true)}
function onHash158(){if(location.hash==='#creator')activateCreator158(false)}
function init158(){installCreatorView158();installShortStudio158();setTimeout(installShortDirect158,80);patchArtifactButtons158();if(location.hash==='#creator')setTimeout(()=>activateCreator158(false),120);window.addEventListener('hashchange',onHash158);document.addEventListener('click',e=>{const b=e.target.closest('.kh-tabs [data-view]');if(b&&b.dataset.view!=='creator'&&location.hash==='#creator')history.replaceState(null,'',location.pathname+location.search)});document.addEventListener('bd:vault-mutated',e=>{const p=String(e.detail?.path||'');if(p.startsWith('/knowledge'))setTimeout(()=>{if($('[data-view-panel="creator"]')?.classList.contains('active'))loadCreator158(false)},180)})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init158,{once:true});else init158();
window.BDCreatorStudio158={open:()=>activateCreator158(true),refresh:()=>loadCreator158(true),openShortFromArtifact:openShortFromArtifact158};
